insert into public.startups (name,tagline,headquarters,founded_year,shutdown_year,funding_amount,funding_usd,funding_stage,business_model,founders,sector,team_size,competitors,key_investors,user_base,logo_url,website_url,status_text,tags,underlying_tech,failure_reason,epitaph,postmortem_url,status,added_by) values ('Stayzilla','Online accommodation marketplace connecting travelers with hotels and homestays across India','Bengaluru, Karnataka, India',2005,2017,'$33.5 Mn',33500000,'Series B','Hotel booking commissions and accommodation marketplace fees',array['Yogendra Vasupal','Rupal Yogendra','Sachit Singhi'],'TravelTech / Hospitality','11-50','OYO, MakeMyTrip, Goibibo, Airbnb','Matrix Partners, Nexus Venture Partners',null,null,'https://www.stayzilla.com','failed',array['TravelTech','Hospitality','Homestays','Hotel Booking','Marketplace'],'Online booking platform, accommodation marketplace technology','High operating costs, weak local network effects, difficulty scaling cost-effectively and insufficient revenue.','A marketplace needs strong local supply and demand density to become economically viable.','https://inc42.com/buzz/startup-shutdowns-india-2017/','published','import') on conflict (name_key) do nothing;
insert into public.startups (name,tagline,headquarters,founded_year,shutdown_year,funding_amount,funding_usd,funding_stage,business_model,founders,sector,team_size,competitors,key_investors,user_base,logo_url,website_url,status_text,tags,underlying_tech,failure_reason,epitaph,postmortem_url,status,added_by) values ('TinyOwl','Restaurant discovery and food ordering application connecting customers with local restaurants','Mumbai, Maharashtra, India',2014,2016,'$27 Mn',27000000,'Series B','Restaurant commissions and food-ordering fees',array['Shikhar Paliwal','Gaurav Choudhary','Saurabh Goyal','Mandad','Tanuj Khandelwal'],'FoodTech / Food Delivery','11-50','Zomato, Swiggy, Foodpanda, Faasos','Sequoia Capital, Matrix Partners, Nexus Venture Partners',null,null,'https://tinyowl.com','failed',array['FoodTech','Food Delivery','Restaurant Marketplace','Mobile Apps','On-Demand'],'Mobile applications, restaurant discovery, online ordering and delivery logistics','Expansion into multiple cities created operational and financial pressure amid intense competition and funding difficulties.','Geographic expansion should follow operational stability and proven unit economics.','https://economictimes.indiatimes.com/small-biz/startups/10-startups-that-shut-down-in-2016/articleshow/56022024.cms','published','import') on conflict (name_key) do nothing;
insert into public.startups (name,tagline,headquarters,founded_year,shutdown_year,funding_amount,funding_usd,funding_stage,business_model,founders,sector,team_size,competitors,key_investors,user_base,logo_url,website_url,status_text,tags,underlying_tech,failure_reason,epitaph,postmortem_url,status,added_by) values ('PepperTap','On-demand grocery delivery platform allowing consumers to order groceries from nearby stores','Gurugram, Haryana, India',2014,2016,'$51.2 Mn',51200000,'Series B','Marketplace commissions and grocery delivery margins',array['Navneet Singh','Milind Sharma'],'Grocery / E-commerce','11-50','Grofers, BigBasket, LocalBanya, ZopNow','SAIF Partners, Sequoia Capital, Snapdeal, InnoVen Capital',null,null,'https://peppertap.com','failed',array['Grocery','E-commerce','Hyperlocal','On-Demand Delivery','Marketplace'],'Mobile commerce, inventory management, delivery logistics','Order volumes declined sharply, competition intensified and the company struggled with the economics of hyperlocal grocery delivery.','High order volumes are meaningless without healthy contribution margins.','https://inc42.com/startups/8-startup-shutdowns-2016/','published','import') on conflict (name_key) do nothing;
insert into public.startups (name,tagline,headquarters,founded_year,shutdown_year,funding_amount,funding_usd,funding_stage,business_model,founders,sector,team_size,competitors,key_investors,user_base,logo_url,website_url,status_text,tags,underlying_tech,failure_reason,epitaph,postmortem_url,status,added_by) values ('Dazo','Online food ordering startup offering curated meal options and food delivery in India','Bengaluru, Karnataka, India',2015,2016,null,null,null,'Meal sales and food delivery commissions',array['Monica Rastogi','Shashaank Shekhar Singhal'],'FoodTech / Food Delivery','10-50','Swiggy, Zomato, TinyOwl, Foodpanda',null,null,null,'https://dazo.in','failed',array['FoodTech','Food Delivery','Meal Ordering','Consumer Internet','Marketplace'],'Mobile applications, online ordering, delivery logistics','Intense competition and insufficient funding prevented the company from sustaining its operations.','Entering a crowded delivery market requires differentiation and sufficient financial runway.','https://economictimes.indiatimes.com/small-biz/startups/10-startups-that-shut-down-in-2016/articleshow/56022024.cms','published','import') on conflict (name_key) do nothing;
